  <script>
    (() => {
      let theme;
      try {
        theme = localStorage.getItem("upb-theme");
      } catch (_) {}
      if (theme !== "light" && theme !== "dark") {
        theme = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
      }
      document.documentElement.dataset.theme = theme;
    })();
  </script>
  <style>
    :root {
      color-scheme: light;
      --bg: #FFF8E7;
      --text: #1D1D1F;
      --muted: #5A5A5F;
      --card: #FFFFFF;
      --accent: #B6432E;
      --accent-ink: #FFFFFF;
      --line: #E9DEC8;
      --soft: #F4EBD8;
      --shadow: 0 0.75rem 2rem rgb(62 47 25 / 8%);
    }

    :root[data-theme="dark"] {
      color-scheme: dark;
      --bg: #14142B;
      --text: #F4F1DE;
      --muted: #B8B5A7;
      --card: #1F1F3D;
      --accent: #E17B5F;
      --accent-ink: #171428;
      --line: #383854;
      --soft: #292944;
      --shadow: 0 0.75rem 2rem rgb(0 0 0 / 20%);
    }

    * { box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
      scroll-padding-top: 2rem;
    }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      font-size: 1rem;
      line-height: 1.6;
      transition: background-color 180ms ease, color 180ms ease;
    }

    a { color: inherit; }

    .shell {
      width: min(100% - 3rem, 74rem);
      margin-inline: auto;
    }

    .masthead {
      position: relative;
      overflow: hidden;
      padding: 1.25rem 0 5rem;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(ellipse at 83% 10%, rgb(182 67 46 / 12%), transparent 34%),
        radial-gradient(ellipse at 8% 90%, rgb(209 159 75 / 14%), transparent 32%);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .wordmark {
      display: inline-flex;
      align-items: center;
      gap: 0.65rem;
      font-size: 0.9rem;
      font-weight: 750;
      letter-spacing: 0.04em;
      text-decoration: none;
    }

    .mark {
      display: grid;
      width: 2.2rem;
      aspect-ratio: 1;
      place-items: center;
      border-radius: 0.75rem;
      background: var(--accent);
      color: var(--accent-ink);
      font-size: 1rem;
      font-weight: 900;
      transform: rotate(-5deg);
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 1.1rem;
    }

    .nav-actions a {
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 650;
      text-decoration: none;
    }

    .nav-actions a:hover { color: var(--accent); }

    #theme-toggle {
      display: inline-grid;
      width: 2.75rem;
      height: 2.75rem;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      background: var(--card);
      color: var(--text);
      cursor: pointer;
      font: inherit;
      font-size: 1.2rem;
      box-shadow: var(--shadow);
    }

    #theme-toggle:focus-visible,
    a:focus-visible {
      outline: 0.2rem solid var(--accent);
      outline-offset: 0.2rem;
    }

    .hero {
      max-width: 52rem;
      padding-top: 5.25rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
      margin: 0 0 1rem;
      color: var(--accent);
      font-size: 0.82rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      width: 1.65rem;
      height: 0.15rem;
      background: currentColor;
      content: "";
    }

    h1 {
      max-width: 13ch;
      margin: 0;
      font-size: 2.5rem;
      line-height: 1.08;
      letter-spacing: -0.045em;
    }

    .hero-copy {
      max-width: 42rem;
      margin: 1.25rem 0 0;
      color: var(--muted);
      font-size: 1.1rem;
    }

    .hero-note {
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
      margin-top: 1.5rem;
      padding: 0.45rem 0.8rem;
      border: 1px solid var(--line);
      border-radius: 99rem;
      background: var(--card);
      color: var(--muted);
      font-size: 0.85rem;
    }

    .hero-note strong { color: var(--text); }

    main { padding-block: 4.5rem 5rem; }

    section + section { margin-top: 5.5rem; }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 2rem;
      margin-bottom: 1.65rem;
    }

    .section-heading h2,
    #future-of-se h2 {
      margin: 0;
      font-size: 1.75rem;
      line-height: 1.2;
      letter-spacing: -0.03em;
    }

    .section-heading p {
      max-width: 34rem;
      margin: 0;
      color: var(--muted);
    }

    .team-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1.1rem;
    }

    .member-card {
      display: flex;
      min-width: 0;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.4rem;
      border: 1px solid var(--line);
      border-radius: 1.15rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .avatar {
      width: 8rem;
      height: 8rem;
      flex: 0 0 auto;
      margin-bottom: 1.1rem;
      border: 0.22rem solid var(--bg);
      border-radius: 50%;
      object-fit: cover;
      box-shadow: 0 0 0 1px var(--line);
    }

    .member-card h3 {
      margin: 0 0 0.25rem;
      font-size: 1.25rem;
      line-height: 1.25;
    }

    .study {
      margin: 0;
      color: var(--muted);
      font-size: 0.86rem;
      font-weight: 650;
    }

    .bio {
      margin: 0.9rem 0 1.2rem;
      color: var(--muted);
      font-size: 0.94rem;
      line-height: 1.6;
    }

    .bio em { color: var(--text); }

    .hot-take {
      width: 100%;
      margin-top: auto;
      padding: 0.7rem 0.8rem;
      border-radius: 0.8rem;
      background: var(--accent);
      color: var(--accent-ink);
      font-size: 0.9rem;
      font-weight: 700;
      line-height: 1.45;
    }

    .future-panel {
      position: relative;
      overflow: hidden;
      padding: clamp(1.5rem, 5vw, 3.5rem);
      border: 1px solid var(--line);
      border-radius: 1.5rem;
      background:
        radial-gradient(ellipse at 100% 0%, rgb(182 67 46 / 12%), transparent 34%),
        var(--card);
      box-shadow: var(--shadow);
    }

    .future-panel .eyebrow { margin-bottom: 0.8rem; }

    .future-panel h2 {
      max-width: 20ch;
      margin-bottom: 1rem !important;
    }

    .future-intro {
      max-width: 52rem;
      margin: 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .future-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      margin-top: 2rem;
    }

    .future-card {
      padding: 1.2rem;
      border: 1px solid var(--line);
      border-radius: 1rem;
      background: var(--bg);
    }

    .future-card h3 {
      margin: 0 0 0.5rem;
      font-size: 1rem;
    }

    .future-card p {
      margin: 0;
      color: var(--muted);
    }

    .future-card strong { color: var(--text); }

    .closing-line {
      margin: 1.3rem 0 0;
      color: var(--accent);
      font-weight: 750;
    }

    footer {
      padding: 1.5rem 1rem;
      border-top: 1px solid var(--line);
      color: var(--muted);
      font-size: 0.8rem;
      text-align: center;
    }

    footer p { margin: 0; }

    @media (max-width: 700px) {
      .shell { width: calc(100% - 2rem); }

      .topbar {
        align-items: flex-start;
        flex-direction: column;
      }

      .nav-actions {
        width: 100%;
        justify-content: space-between;
      }

      .hero { padding-top: 3.5rem; }

      .masthead { padding-bottom: 3.5rem; }

      .section-heading {
        align-items: flex-start;
        flex-direction: column;
        gap: 0.65rem;
      }

      .team-grid { grid-template-columns: 1fr; }

      .member-card {
        display: grid;
        grid-template-columns: 5rem minmax(0, 1fr);
        column-gap: 1rem;
        align-items: start;
      }

      .avatar {
        grid-row: 1 / span 3;
        width: 5rem;
        height: 5rem;
        margin: 0;
      }

      .member-card h3 { align-self: end; }

      .study { grid-column: 2; }

      .bio,
      .hot-take { grid-column: 1 / -1; }

      .bio { margin-bottom: 1rem; }

      .future-grid { grid-template-columns: 1fr; }

      section + section { margin-top: 4rem; }

      main { padding-block: 3rem 4rem; }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
