    <div class="shell">
      <div class="topbar">
        <a class="wordmark" href="#top" aria-label="The Merge Conflicts, home">
          <span class="mark" aria-hidden="true">{ }</span>
          <span>AGENTIC SE LAB · TEAM PAGE</span>
