  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Team The Merge Conflicts | Agentic SE Lab</title>
  <script>
    (() => {
      let theme;
      try {
        theme = localStorage.getItem("upb-theme");
      } catch (_) {}
      if (theme !== "light" && theme !== "dark") {
        theme = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
      }
      document.documentElement.setAttribute("data-theme", theme);
    })();
  </script>
  <style>
    :root {
      --accent: #E4007C;
      --accent-ink: #FFFFFF;
    }

    [data-theme="light"] {
      color-scheme: light;
      --bg: #FFF8E7;
      --text: #1D1D1F;
      --muted: #5A5A5F;
      --card: #FFFFFF;
      --line: #E9DEC8;
      --soft: #F4EBD8;
      --shadow: 0 0.75rem 2rem rgb(62 47 25 / 8%);
    }

    [data-theme="dark"] {
      color-scheme: dark;
      --bg: #14142B;
      --text: #F4F1DE;
