      scroll-padding-top: 2rem;
    }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      font-size: 1rem;
      line-height: 1.6;
      transition: background-color 180ms ease, color 180ms ease;
    }

    a { color: inherit; }

    .shell {
      width: min(100% - 3rem, 74rem);
      margin-inline: auto;
    }

    .masthead {
      position: relative;
      overflow: hidden;
      padding: 1.25rem 0 5rem;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(ellipse at 83% 10%, rgb(228 0 124 / 10%), transparent 34%),
