      font-weight: 750;
      letter-spacing: 0.04em;
      text-decoration: none;
    }

    .mark {
      display: grid;
      width: 2.2rem;
      aspect-ratio: 1;
      place-items: center;
      border-radius: 0.75rem;
      background: var(--accent);
      color: var(--accent-ink);
