    }

    .nav-actions a:hover { color: var(--accent); }

    #theme-toggle {
      display: inline-grid;
      width: 2.75rem;
      height: 2.75rem;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      background: var(--card);
      color: var(--text);
