      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      margin-top: 2rem;
    }

    .future-card {
      padding: 1.2rem;
      border: 1px solid var(--line);
      border-radius: 1rem;
      background: var(--bg);
    }

    .future-card h3 {
      margin: 0 0 0.5rem;
      font-size: 1rem;
    }

    .future-card p {
      margin: 0;
      color: var(--muted);
    }

    .future-card strong { color: var(--text); }

    .closing-line {
      margin: 1.3rem 0 0;
      color: var(--accent);
      font-weight: 750;
    }

    footer {
      padding: 1.5rem 1rem;
