  <footer>
    <p>Built by an agent, supervised by humans. · 2026 · The Merge Conflicts</p>
  </footer>

  <script>
    (() => {
      const button = document.getElementById("theme-toggle");

      function updateButton(theme) {
        const isDark = theme === "dark";
        button.textContent = isDark ? "☀" : "☾";
        button.setAttribute("aria-label", isDark ? "Switch to day mode" : "Switch to night mode");
        button.setAttribute("title", isDark ? "Switch to day mode" : "Switch to night mode");
      }

      updateButton(document.documentElement.getAttribute("data-theme") || "light");

      button.addEventListener("click", () => {
        const next = document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark";
        document.documentElement.setAttribute("data-theme", next);
        updateButton(next);
        try {
          localStorage.setItem("upb-theme", next);
        } catch (_) {}
      });
    })();
  </script>
